import { data } from '@takaro/helpers';
import {
  MINUTE_MS,
  getState,
  humanDuration,
  compileSchedules,
  makeZoneReader,
  firstScheduledBetween,
} from './rm-helpers.js';

const LOOKAHEAD_MS = 8 * 24 * 60 * 60 * 1000;

async function main() {
  const { gameServerId, pog, module: mod } = data;
  const config = mod.userConfig;
  const now = Date.now();
  const state = await getState(gameServerId, mod.moduleId);
  const pending = state.pending;

  if (pending && pending.postponed) {
    const maxDelay = Math.max(0, Number(config.maxDelayMinutes) || 0) * MINUTE_MS;
    const resume = Math.max(1, Number(config.resumeCountdownMinutes) || 5) * MINUTE_MS;
    const latest = new Date(pending.originalAt).getTime() + maxDelay + resume - now;
    await pog.pm(
      `The server restart is on hold: ${pending.postponed.reason}. It runs when it is safe, at the latest in about ${humanDuration(latest)}.`,
    );
    return;
  }
  if (pending) {
    await pog.pm(`The server restarts in ${humanDuration(new Date(pending.at).getTime() - now)}.`);
    return;
  }

  const lastScheduled = state.lastScheduledAt ? new Date(state.lastScheduledAt).getTime() : 0;
  const next = firstScheduledBetween(
    compileSchedules(config),
    makeZoneReader(config.timezone),
    Math.max(now, lastScheduled + 1),
    now + LOOKAHEAD_MS,
  );
  if (next === null) {
    await pog.pm('No server restart is scheduled.');
    return;
  }
  await pog.pm(`Next server restart in ${humanDuration(next - now)}.`);
}

await main();

import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import {
  MINUTE_MS,
  MANAGE_PERMISSION,
  getState,
  setState,
  getSetting,
  warningList,
  sendWarning,
  executeRestart,
} from './rm-helpers.js';

async function main() {
  const { gameServerId, pog, player, arguments: args, module: mod } = data;
  const config = mod.userConfig;
  const moduleId = mod.moduleId;
  const prefix = await getSetting('commandPrefix', gameServerId, '/');

  if (!checkPermission(pog, MANAGE_PERMISSION)) {
    throw new TakaroUserError(`Only admins can restart the server. Type ${prefix}restartstatus to see when the next restart is.`);
  }

  const minutes = Number(args.minutes);
  if (!Number.isInteger(minutes) || minutes < 0 || minutes > 1440) {
    throw new TakaroUserError(`Usage: ${prefix}restartnow <minutes 0-1440>. 0 restarts right away.`);
  }

  const now = Date.now();
  const state = await getState(gameServerId, moduleId);
  const ctx = { prefix };

  if (minutes === 0) {
    state.pending = null;
    state.lastRestartAt = new Date(now).toISOString();
    await setState(gameServerId, moduleId, state);
    await pog.pm('Restarting the server now.');
    await executeRestart({ gameServerId, config, ctx });
    return;
  }

  const replaced = Boolean(state.pending);
  const at = new Date(now + minutes * MINUTE_MS).toISOString();
  state.pending = {
    id: `admin-${now}`,
    at,
    originalAt: at,
    source: 'admin',
    by: player ? player.name : null,
    warned: warningList(config).filter((w) => w >= minutes),
    // An admin restart skips the safe-window checks: the admin decided.
    forced: true,
    postponed: null,
    // Players hear about it right away, so a cancel must be announced too.
    announced: true,
  };
  await setState(gameServerId, moduleId, state);
  await sendWarning(gameServerId, config, minutes * MINUTE_MS, ctx, true);
  await pog.pm(
    `${replaced ? 'Restart moved' : 'Restart set'}: in ${minutes} min. Type ${prefix}restartcancel to stop it.`,
  );
}

await main();

import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import {
  MANAGE_PERMISSION,
  getState,
  setState,
  getSetting,
  fill,
  humanDuration,
  broadcast,
  announceDiscord,
  compileSchedules,
  makeZoneReader,
  firstScheduledBetween,
} from './rm-helpers.js';

const LOOKAHEAD_MS = 8 * 24 * 60 * 60 * 1000;

async function main() {
  const { gameServerId, pog, module: mod } = data;
  const config = mod.userConfig;
  const moduleId = mod.moduleId;
  const prefix = await getSetting('commandPrefix', gameServerId, '/');

  if (!checkPermission(pog, MANAGE_PERMISSION)) {
    throw new TakaroUserError(`Only admins can cancel a restart. Type ${prefix}restartstatus to see when the next restart is.`);
  }

  const now = Date.now();
  const state = await getState(gameServerId, moduleId);

  if (state.pending) {
    const announced =
      Boolean(state.pending.announced) || (state.pending.warned || []).length > 0 || Boolean(state.pending.postponed);
    state.pending = null;
    await setState(gameServerId, moduleId, state);
    if (announced) {
      const message = fill(config.cancelMessage, { prefix });
      await broadcast(gameServerId, message);
      await announceDiscord(config, message);
    }
    await pog.pm('Restart cancelled.');
    return;
  }

  // Nothing counting down yet: skip the next scheduled restart instead.
  const lastScheduled = state.lastScheduledAt ? new Date(state.lastScheduledAt).getTime() : 0;
  const next = firstScheduledBetween(
    compileSchedules(config),
    makeZoneReader(config.timezone),
    Math.max(now, lastScheduled + 1),
    now + LOOKAHEAD_MS,
  );
  if (next === null) {
    throw new TakaroUserError('No restart is planned, so there is nothing to cancel.');
  }
  state.lastScheduledAt = new Date(next).toISOString();
  await setState(gameServerId, moduleId, state);
  await pog.pm(`Skipped the next scheduled restart (it was due in ${humanDuration(next - now)}).`);
}

await main();

